"""Edge-case tests for model-diagnostics — generated by bug-hunter agent."""
from __future__ import annotations

import numpy as np
import polars as pl
import pytest

import ferrum
from ferrum._diagnostics.precomputed import _PrecomputedSource
from ferrum._diagnostics.sources._base import BaseSource, _coerce_X_y
from ferrum._diagnostics.sources._classification import _coerce_class_label
from ferrum._diagnostics.sources._compared import ComparedModelSource


# ---------------------------------------------------------------------------
# Minimal duck-typed models for adversarial testing
# ---------------------------------------------------------------------------


class _MinimalPredict:
    """Model with only predict — no proba, no coef_, no feature_importances_."""
    def predict(self, X):
        if hasattr(X, '__len__'):
            return np.zeros(len(X))
        return np.zeros(X.shape[0])


class _PredictProba:
    """Binary classifier with predict + predict_proba."""
    classes_ = np.array([0, 1])

    def predict(self, X):
        n = len(X) if hasattr(X, '__len__') else X.shape[0]
        return np.zeros(n, dtype=int)

    def predict_proba(self, X):
        n = len(X) if hasattr(X, '__len__') else X.shape[0]
        return np.column_stack([np.full(n, 0.6), np.full(n, 0.4)])


class _PredictProbaMulticlass:
    """Three-class classifier with predict + predict_proba."""
    classes_ = np.array([0, 1, 2])

    def predict(self, X):
        n = len(X) if hasattr(X, '__len__') else X.shape[0]
        return np.zeros(n, dtype=int)

    def predict_proba(self, X):
        n = len(X) if hasattr(X, '__len__') else X.shape[0]
        return np.column_stack([np.full(n, 0.7), np.full(n, 0.2), np.full(n, 0.1)])


class _LinearModel:
    """Model that exposes coef_ (linear model protocol)."""
    coef_ = np.array([1.0, -0.5, 0.3])

    def predict(self, X):
        if isinstance(X, pl.DataFrame):
            X = X.to_numpy()
        return X @ self.coef_


class _DecisionFunctionModel:
    """Binary model with only decision_function (like LinearSVC)."""
    classes_ = np.array([0, 1])

    def predict(self, X):
        n = len(X) if hasattr(X, '__len__') else X.shape[0]
        return np.zeros(n, dtype=int)

    def decision_function(self, X):
        n = len(X) if hasattr(X, '__len__') else X.shape[0]
        return np.linspace(-2, 2, n)


class _ClustererModel:
    """Model that exposes labels_ and cluster_centers_."""
    labels_ = np.array([0, 0, 1, 1, 2])
    cluster_centers_ = np.array([[1, 0], [0, 1], [-1, 0]], dtype=np.float64)
    n_clusters = 3

    def predict(self, X):
        n = len(X) if hasattr(X, '__len__') else X.shape[0]
        return np.zeros(n, dtype=int)


# ---------------------------------------------------------------------------
# Category: Null / NaN handling
# ---------------------------------------------------------------------------


def test_predictions_with_nan_in_features():
    """NaN in feature columns should not panic the Rust hat_matrix_stats path."""
    X = pl.DataFrame({"f0": [1.0, float("nan"), 3.0], "f1": [4.0, 5.0, 6.0], "f2": [7.0, 8.0, 9.0]})
    y = pl.Series("y", [1.0, 2.0, 3.0])
    model = _LinearModel()
    source = ferrum.ModelSource(model, X, y)
    # This exercises the hat_matrix_stats Rust code with NaN in the design matrix.
    # It should not panic — NaN should propagate to the output.
    pred = source.predictions()
    assert pred.height == 3
    # y_pred should contain NaN because the model multiplied through NaN inputs
    assert pred["y_pred"].is_nan().any()


def test_predictions_with_nan_in_y():
    """NaN in y_true should propagate to residuals, not cause a panic."""
    X = pl.DataFrame({"f0": [1.0, 2.0, 3.0]})
    y = pl.Series("y", [1.0, float("nan"), 3.0])
    model = _MinimalPredict()
    source = ferrum.ModelSource(model, X, y)
    pred = source.predictions()
    assert pred.height == 3
    # Residual at row 1 should be NaN because y_true is NaN
    residuals = pred["residual"].to_list()
    assert np.isnan(residuals[1])


def test_confusion_matrix_with_nan_predictions_raises():
    """Confusion matrix with NaN in predictions should not produce nonsensical output."""
    y_true = np.array([0, 1, 1, 0])
    y_pred = np.array([0, 1, float("nan"), 0])
    src = _PrecomputedSource(y_true, y_pred)
    # This may raise due to NaN class labels, or produce a matrix with NaN row.
    # Either is acceptable as long as it doesn't silently produce wrong results.
    try:
        cm = src.confusion_matrix()
        # If it doesn't raise, verify the matrix is valid
        assert cm.height > 0
    except (ValueError, TypeError):
        # Expected — NaN is not a valid class label
        pass


