    y_pred = np.array([1e15 + 1, 2e15 + 1, 3e15 + 1])
    chart = ferrum.residuals_chart(y_true=y_true, y_pred=y_pred, panels="single")
    svg = chart.show_svg()
    assert "<svg" in svg
    assert "Infinity" not in svg


