def test_compared_model_source_repr():
    """ComparedModelSource repr should show model names."""
    X = pl.DataFrame({"f0": [1.0, 2.0]})
    y = pl.Series("y", [0, 1])
    cms = ferrum.ModelSource.compare({"alpha": _PredictProba(), "beta": _PredictProba()}, X, y)
    r = repr(cms)
