def test_residuals_visualizer_double_fit():
    """Calling fit() twice should not error and should use the latest data."""
    X1 = pl.DataFrame({"f0": [1.0, 2.0, 3.0]})
    y1 = pl.Series("y", [1.0, 2.0, 3.0])
    X2 = pl.DataFrame({"f0": [10.0, 20.0, 30.0]})
    y2 = pl.Series("y", [10.0, 20.0, 30.0])
    model = _MinimalPredict()
    viz = ferrum.ResidualsVisualizer(model)
    viz.fit(X1, y1)
    svg1 = viz.show().show_svg()
    viz.fit(X2, y2)
    svg2 = viz.show().show_svg()
    # Both should produce valid SVGs, and they should differ
    assert "<svg" in svg1
    assert "<svg" in svg2


